using System;
using System.Collections.Generic;

class Program
{
    static int DigitsCount(int n)
    {
        if (n == 0)
        {
            return 1;
        }
        int count = 0;
        while (n > 0)
        {
            n = n / 10;
            count = count + 1;
        }
        return count;
    }
}

