using System;
using System.Collections.Generic;

class Program
{
    static int BinaryGuess(int secret)
    {
        int lo = 1;
        int hi = 100;
        int tries = 0;
        while (true)
        {
            int mid = (lo + hi) / 2;
            tries = tries + 1;
            if (mid == secret)
            {
                return tries;
            }
            if (mid < secret)
            {
                lo = mid + 1;
            }
            else
            {
                hi = mid - 1;
            }
        }
    }
}
